def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count numbers with equally many even and odd digits, divisible by k."""
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        n = len(digits)

        @lru_cache(None)
        def dp(pos: int, balance: int, remainder: int, tight: bool) -> int:
            if pos == n:
                return int(balance == 0 and remainder == 0)
            upper = digits[pos] if tight else 9
            total = 0
            first = 1 if pos == 0 else 0
            for digit in range(first, upper + 1):
                next_tight = tight and digit == upper
                next_balance = balance + (1 if digit % 2 == 0 else -1)
                total += dp(pos + 1, next_balance,
                            (remainder * 10 + digit) % k, next_tight)
            return total

        return dp(0, 0, 0, True)

    return count_up_to(high) - count_up_to(low - 1)"}
